(window.IBALL_PERIODICAL_LIBRARY = window.IBALL_PERIODICAL_LIBRARY || {})["2026-08-17"] = {"meta":{"id":"2026-08-17","label":"2026 年 8 月 17 日 - 8 月 23 日","date":"2026-08-17","range":"2026-08-17|2026-08-23","theme":"","themes":[],"sources":["The Guardian","Economist"],"title":"‘Shanghai turns into the sea’ as","titleZh":"（8.17—8.23）","counts":{"article":7,"paragraph":20,"vocab":16,"question":15,"qa":0,"original":6,"layout":1},"tabs":{"articles":true,"reading":true,"tests":true,"qa":false,"originals":true}},"articles":[{"file":"8.17—8.23 原文.docx","articles":[{"title":"‘Shanghai turns into the sea’ as Typhoon Dolphin inundates China’s east coast","titleZh":"","source":"The Guardian","publishedOn":"8.17","paragraphs":[{"index":1,"text":"Torrential rain and storms in Typhoon Dolphin’s wake have inundated China’s eastern coastal region and flooded streets in Shanghai, where about 40% of flights were grounded yesterday due to the weather."},{"index":2,"text":"Dolphin packed maximum sustained winds of 94mph near its centre when it made landfall in Zhejiang, south of Shanghai, on Sunday before weakening to a tropical storm."},{"index":3,"text":"More than 1.2million people across Fujian province and the cities of Wenzhou and Shanghai were moved to safety as the typhoon approached."},{"index":4,"text":"Many streets in Shanghai, the country’s second most populous city, were flooded, including in the main commercial centres."},{"index":5,"text":"The city’s two airports cancelled 943 flights as a result of the typhoon, the state broadcaster CCTV said."},{"index":6,"text":"A weather station in central Shanghai yesterday recorded nearly 313mm (12in) of rain in the 24 hours to 7am local time, its highest 24-hour rainfall in more than 150 years of records. Another station in the city recorded nearly 400mm."},{"index":7,"text":"The hashtag “Shanghai turns into the sea” began trending on the Chinese social media platform Weibo as videos circulated showing flooded streets around Wukang Mansion, one of the city’s best-known landmarks."},{"index":8,"text":"“It rained almost all night last night. When I woke up this morning, I found the neighbourhood flooded,” said 39-year-old Hou Lina, who works in sales in Jiading in Shanghai."},{"index":9,"text":"“I’ve lived in Shanghai for 10 years, and this is the first time I’ve experienced such inconvenience from a typhoon. This is the first time I’ve encountered such widespread flooding,” she said."},{"index":10,"text":"In Shanghai’s Jinshan, the district authority said non-essential businesses and organisations could temporarily halt operations, classes, outdoor events and transit services, amid forecasts of continued strong winds and heavy rain."},{"index":11,"text":"Authorities warned that 74 rivers in the Taihu Lake basin and the coastal areas of eastern Zhejiang had exceeded warning levels, and that flood risks for small and medium-sized rivers in heavy rainfall areas were high."},{"index":12,"text":"The strongest typhoon to hit China this year, Dolphin is forecast to move inland to the central provinces of Hubei and Henan in the coming days, while also pushing moisture north."},{"index":13,"text":"Authorities in Beijing warned of torrential rain and said the capital was prepared to activate its flood control response this morning."},{"index":14,"text":"Beijing was expected to experience “significant rainfall” from today until Thursday, with authorities warning of flash floods in the city and landslides in surrounding mountains."},{"index":15,"text":"The typhoon travelled 6,000km (3,728 miles) before making landfall, giving it a life cycle three times longer than a typical typhoon, and bringing an ultra-large cloud system that enveloped China’s east, CCTV said."},{"index":16,"text":"Dolphin’s impact was being compared with 2023’s Typhoon Doksuri, which crossed the country after causing destruction in south-eastern Fujian province, unleashing record rainfall on Beijing."},{"index":17,"text":"CCTV said Beijing, Tianjin and Hebei would need to brace for heavy rain into Thursday as the storm clouds met colder air in the north."},{"index":18,"text":"On China’s southern coast, Hong Kong reached 36.9C on Sunday, which the Hong Kong Observatory said marked its hottest day since records began in 1884."},{"index":19,"text":"The forecaster Tropical Storm Risk said it expected the 2026 north-west Pacific typhoon season to be one of the most active on record and to include 28 tropical storms, 20 typhoons and 13 intense typhoons."},{"index":20,"text":"It said the continuing strong El Niño event, high activity to date and weaker-than-usual trade winds across the north-west Pacific basin were key reasons for the intensity of the typhoon season."}]},{"title":"Pet detectives: dogs can tell fearful from angry or sad human faces, research finds","titleZh":"","source":"The Guardian","publishedOn":"8.18","paragraphs":[{"index":1,"text":"While humans keep a close eye on their pets, it seems our pets are keeping a close eye on us too, as a study has revealed dog brains can distinguish between different types of unhappy human expressions."},{"index":2,"text":"Dogs whose brain activity was monitored not only distinguished happy faces from other expressions, but could tell fearful faces apart from those that are angry or sad, researchers found."},{"index":3,"text":"Dr Laura Cuaya said: “This is the first demonstration that the dog brain can distinguish between emotions from the same valence [positive or negative character],” she said."},{"index":4,"text":"Writing in the journal iScience, Cuaya and colleagues from the University of Vienna described working with pet dogs that had been trained to lie still, awake and unrestrained, within an MRI scanner."},{"index":5,"text":"In the first experiment, eight dogs were shown five sets of happy faces and five sets of neutral faces. Each set contained four photos of humans that were unfamiliar to the dog but were of the same gender as their primary caregiver. This was repeated five times for each dog."},{"index":6,"text":"The results revealed increased activity in certain parts of the brain when the dogs were shown happy faces compared with neutral ones. Cuaya said these areas were associated with higher visual processing, social processing and reward processing – suggesting the dog was experiencing something positive."},{"index":7,"text":"Dr Raúl Hernández Pérez, the first author of the study, said the results raised another question, however: “We don’t know if these regions are related just to happy faces or to emotional faces in general.”"},{"index":8,"text":"The team then carried out a second MRI experiment involving 12 dogs. Each was shown new sets of unfamiliar male and female human faces, this time bearing four different expressions: happiness, sadness, fear and anger."},{"index":9,"text":"The researchers used machine learning to analyse activity in the same brain regions identified in the first experiment, revealing that the animals could distinguish happy faces from each negative expression – but could not distinguish between different types of unhappy face."},{"index":10,"text":"However, when activity across the whole dog brain was analysed, the researchers found it was possible to distinguish between sad v fearful faces, and angry v fearful faces – but not between angry and sad faces."},{"index":11,"text":"Hernández said different negative expressions may trigger different responses in dogs as they represented different types of threat."},{"index":12,"text":"Cuaya said previous behavioural studies had shown dogs can tell apart some human facial expressions, but that they tended to only test two at a time, one positive and one negative."},{"index":13,"text":"The authors said it might be harder for dogs to tell apart two human facial expressions if they were both negative or both positive, and dogs might also need additional information – such as body language – to distinguish anger from sadness."},{"index":14,"text":"The research has limitations, including its small sample size; the fact that most of the dogs were border collies, and all were healthy and without behavioural problems."},{"index":15,"text":"Cuaya said the study could have practical implications: for example, expressing happiness when training a dog could aid the learning process."},{"index":16,"text":"Bridget Waller, a professor of evolution and social behaviour at Nottingham Trent University, who was not involved in the study, described the work as fascinating, saying it showed how “dogs have been shaped through domestication to understand human behaviour”."},{"index":17,"text":"“Smiling is the most commonly used human facial expression, vital to our social interactions, and so it makes sense that dogs have developed a particular ability to distinguish this from other facial movements,” she said. “It seems less clear that they can distinguish between the other expressions, and this would make sense as these are less commonly produced in human social interaction.”"}]},{"title":"Paying the price for not investing in our youth","titleZh":"","source":"The Guardian","publishedOn":"8.19","paragraphs":[{"index":1,"text":"Most people think Britain is not working as it should. For young people, the situation is at its most acute: only one in four believe that everyone in society has a fair crack. Most think the game is rigged."},{"index":2,"text":"It is clear why the generation who grew up in the post-2008 crash austerity years as well as Covid are downbeat: the level of public service provision their parents enjoyed is gone, living costs are rising, the AI revolution is changing everything, and the planet is on fire."},{"index":3,"text":"That is why Alan Milburn’s review into youth unemployment is vital. Britain missing out on the talents of 1 million young people not in education, employment or training (Neet) is a problem that extends beyond the jobs market. It is about how the building blocks of a just and prosperous economy have been whittled away, and is a call to action to put things right."},{"index":4,"text":"As with so many of the country’s problems right now, some of the big drivers of youth inactivity stem from the austerity years. That is not to say that other contributing factors – not least Labour’s management of the economy, AI upending youth jobs, and the cost of living crisis – are not playing a role. But there is mounting evidence the consequences of the Tory spending cuts are maturing with disastrous consequences."},{"index":5,"text":"Milburn says the risk of a child becoming Neet can be traced to their earliest years in preschool. To look back, therefore, at the past 16 years of change in education policy, youth services and the public sector more broadly – the lifespan of the generation just entering the workforce – is instructive."},{"index":6,"text":"Across the board, funding has been cut. Within youth services in England, spending is down by 76%, a loss of £1.3bn. Thousands of youth clubs have been closed and social workers lost. The per-pupil level of spending for schools in England was frozen for 14 years. Investment in school buildings, many of which have been affected by the Raac – or crumbling concrete – crisis, also collapsed by a quarter."},{"index":7,"text":"The situation is stark in the Neet crisis. For every £1 the state spends on employment support for young people, it shells out £25 on benefits. With the rise in inactivity for a generation cut adrift, the cost is only going to climb without intervention."},{"index":8,"text":"It is a pattern repeated across government. Rather than investing in public services early to stop problems from developing, the state is in firefighting mode. For Andy Burnham, the task will be to end this shortsighted approach by rebuilding what the thinktank Demos calls a preventive state – a model involving investment to support the foundations of society. The size of the economic, fiscal and social prize would be substantial."},{"index":9,"text":"The challenge for ministers is that the cost to the economy and to government finances of the Neet crisis is £125bn a year and rising. Getting more young people into work would, though, revitalise the life chances of millions and drive up labour participation – boosting the economy and public finances."},{"index":10,"text":"Before the autumn budget, there is a compelling argument for Burnham’s government to take action. However, building a preventive state will come with challenges for a prime minister hemmed in by the UK’s current tight fiscal predicament, and who is in a hurry to show progress."},{"index":11,"text":"Moving money upstream is difficult because the savings from preventive spending take time to materialise, and spending on acute need and welfare cannot be simply turned off. Nowhere is this clearer than early-years services, where changes can take a lifetime to show up in the numbers."},{"index":12,"text":"That timing problem is why the Treasury has often been sceptical. The costs appear immediately, while the savings arrive years later – often benefiting a different government. The incentives favour firefighting over fixing."},{"index":13,"text":"However, refusing to make the transition is a bad choice. Britain is already paying the price of a crumbling NHS, rising welfare bill, jobs market inactivity, and consequent weak economic growth."},{"index":14,"text":"Milburn’s review is therefore a critical test of whether Britain will grasp the nettle to rebuild a preventive state from the ashes of the austerity years. The alternative is to settle for a country hamstrung by the costs of failure, where young people feel lost."}]},{"title":"Screening for success","titleZh":"","source":"Economist","publishedOn":"8.20","paragraphs":[{"index":1,"text":"Having transformed human life, Silicon Valley is now coming for birth. A spate of startups offer screening services that allow couples having children via in-vitro fertilisation (IVF) to assess embryos based on their genetic risk of diseases such as breast cancer and diabetes. Some venture further into science-fiction territory, providing scores for IQ and height, or even eye and hair colour."},{"index":2,"text":"Critics are dismayed. Some worry firms are pushing immature technology onto vulnerable couples. Others say that even if the tech works, its use is immoral. Both arguments contain kernels of truth; neither is ultimately convincing. Banning or heavily restricting embryo screening would be a mistake."},{"index":3,"text":"For now, the debate is a niche concern. The startups mostly cater to the rich, famous and odd. Yet that will change. A wave of investment means that the cost of IVF is likely to fall. If offered embryo screening at the same time, many couples will take it. One survey suggests that three-quarters of Americans support screening embryos for diseases; about a third say the same for non-disease traits. And that is before competitive pressure kicks in. Who wants to see their child bested by genetically selected classmates?"},{"index":4,"text":"Many medics—including nearly every genetics and reproductive-medicine group in the rich world—question whether such “polygenic” prediction is ready for consumers. In Britain, where fertility is more regulated than in America, selecting an embryo on the basis of non-approved factors is unlawful."},{"index":5,"text":"There are indeed reasons for caution. Polygenic scores are tricky. For many diseases caused by a single gene, testing offers near-certainty: if an embryo has the material, it will develop the condition. Yet an assessment of multiple genes leads to risk estimates, rather than a binary answer—and such estimates are more accurate for people with European ancestry, because they are better represented in genetic databases."},{"index":6,"text":"Further caveats are in order. Risk reductions can look large in relative terms but be small in absolute ones, particularly for rare diseases. Selecting for some traits may raise the risk of other less desirable ones. Even for highly genetically determined traits like height, parents remain limited by the range found in their own embryos."},{"index":7,"text":"These facts are an argument for disclosure, however, rather than legal restrictions or outright bans. If companies want to offer polygenic scoring, they must adequately communicate the technology’s limits and risks. They should also let their tests undergo independent scrutiny. This will not scupper a nascent business, since the startups are not, as some critics allege, selling snake oil. A study in 2019 found that parents choosing from among ten embryos may be able to boost their child’s height by 1-6cm and IQ by between one and seven points—with tech that is now nearly a decade old. As genetic databases get better and cover broader populations, and AI draws out the relationship between genes and traits, scores will improve."},{"index":8,"text":"Such progress will raise difficult ethical questions. Some, including the “Make America Healthy Again” movement, argue that fertility tech corrupts what should be a natural process. Others worry that if polygenic screening is limited to the rich, their offspring will have another unfair advantage. The scariest critique is that fertility entrepreneurs are this century’s eugenicists."},{"index":9,"text":"But none of these arguments stands up to scrutiny. “Unnatural” technology is already used in many modern births: this argument against embryo selection just as easily applies to IVF, for instance, which only zealots want banned. Costs should come down, making screening more widely available. And there is a big difference between the murderous coercion of early-20th-century eugenics programmes and parents seeking as much knowledge as possible when picking an embryo."},{"index":10,"text":"Couples desperate for a clever child might be better advised to focus on what happens after birth. Yet so long as parents understand there is no such thing as the perfect baby, the state should not stand in the way of a bit more information. August 15TH- 21ST ｜Leaders"}]},{"title":"Opening time","titleZh":"","source":"Economist","publishedOn":"8.21","paragraphs":[{"index":1,"text":"Even in the most remote corner of China a frothy Fulujia beer is waiting for you. The company, whose name translates as “Lucky Deer”, has opened more than 3,200 mini-pubs across the country since 2021, making it the world’s largest bar chain. More impressive than its scale are its prices. A pint is poured for as little as 5.9 yuan ($0.87), whether it is served in a big city or a border town."},{"index":2,"text":"Fulujia premises are small but uniform micro-watering holes that have 20 beers on draft and a bijou seating area. They often sell bar snacks such as fried pork and edamame beans. When asked why prices are so low, the proprietor of a recently opened Fulujia in Lushui, a town in the deep south-west, says it is because the company is owned by Mixue Bingcheng, a tea and cold-drinks mega-chain that has around 60,000 outlets worldwide. Last year it overtook McDonald’s, the American burger giant, to become the world’s largest fast-food operator by number of locations."},{"index":3,"text":"Mixue bought a controlling stake in Fulujia in October. Both are run on similar franchise models. Franchisees pay an upfront cost of about 60,000 yuan for everything that is needed to launch a mini-pub, such as beer pumps and branded decorations (though rent and renovation costs are not included). They are exempt from paying royalties for three years."},{"index":4,"text":"The secret to Mixue’s success is its mastery of supply chains. It is often described as a logistics company rather than a fast-food chain. The efficiency with which Mixue has been able to move supplies has kept costs for consumers remarkably low—its marquee drink is a four-yuan lemonade. Fulujia uses the same logistics networks to ship its beer from Henan province, where both Mixue and Fulujia are based, to its franchisees, who do not pay transport costs, even when they are as far away as Lushui, more than 2,000km from the brewery."},{"index":5,"text":"A franchising model coupled with a highly efficient supply chain has turbocharged the openings of Mixue outlets—roughly 40 a day appeared in 2025. The effects have been similar for Fulujia. Nearly two-thirds of its 3,200 bars have been launched since Mixue bought its stake late last year. This also appears to be working for the group’s café chain, Lucky Cup, of which there were at least 10,000 in China at the end of last year."},{"index":6,"text":"The model is enjoying some success outside China, too. Mixue has around 5,000 outlets abroad, making it by far the most successful Chinese fast-food chain outside the country. It has also opened Lucky Cup branches in Malaysia and Thailand. Fulujia has not yet announced plans to go overseas. But with pubs in New York and London serving up painfully expensive pints, cheap Chinese brews would be sure to receive a welcome from drinkers. August 15TH- 21ST ｜Business"}]},{"title":"Under a cloud","titleZh":"","source":"Economist","publishedOn":"8.22","paragraphs":[{"index":1,"text":"In 2015, as South-East Asia was engulfed in toxic smog caused by fires in Indonesia, Jusuf Kalla, the country’s vice-president at the time, suggested that his neighbours needed a change in perspective. “For 11 months they enjoyed nice air from Indonesia and they never thanked us,” he said. South-East Asians flocked to a satirical website created to express gratitude to Indonesia. The site has registered more than 34m votes of sarcastic thanks."},{"index":2,"text":"That number may soon grow. Fears of another severe haze are rising as fires rage in Indonesia. Weather-watchers estimate that the number of blazes detected across the island of Borneo in the first 12 days of August alone exceeds the figure registered during the entire month in each of the past seven years. The smoke is already forcing officials to act. In Pontianak, the capital of the Indonesian province of West Kalimantan, schools have shut. In neighbouring Sarawak, in Malaysia, officials urged people to stay indoors. Singapore has put its own responders on standby."},{"index":3,"text":"Meteorologists fear that much worse is to come. El Niño, a weather pattern associated with unusually warm waters in the Pacific, tends to cause drier conditions in the region. This increases the chance of fires, especially on Indonesia’s peatlands, where the carbon-rich soil is more combustible and where fires smouldering underground are hard to extinguish. Many climatologists think that this year’s El Niño will turn out to be the strongest yet, raising concerns about a haze episode comparable to the one in 2015."},{"index":4,"text":"That would be a disaster. The smog in 2015 caused some 100,000 excess deaths in Indonesia, Malaysia and Singapore, according to one study. But there was also a heavy economic toll: the World Bank put Indonesia’s losses at $16.1bn, almost 2% of GDP. Economies in the region are already vulnerable, having been hit to varying degrees by the war in Iran."},{"index":5,"text":"That war could also contribute to the haze. The blockade of the Strait of Hormuz has pushed up fuel and fertiliser costs, prompting the Indonesian government to mandate greater use of biofuels. This, in turn, is driving up the demand for palm oil, putting pressure on farmers and plantation companies to clear more land with fire."},{"index":6,"text":"The region may be better prepared than it was a decade ago. Better satellite monitoring has improved forecasts. A centre in Singapore tracks fires and smoke across the region and provides early warnings, allowing governments to implement public-health measures. In April ASEAN, the regional bloc, inaugurated the secretariat of a new haze-control centre in Jakarta, Indonesia’s capital, which seeks to improve co-ordination between governments."},{"index":7,"text":"But for all the machinery of regional co-operation, it still lacks much bite. ASEAN has had an agreement on transboundary haze since 2002, but implementation and enforcement rest with national governments. Its fund to pay for anti-haze resources, such as water-bombing aircraft and other firefighting equipment, relies on voluntary contributions and remains small."},{"index":8,"text":"Ultimately, the severity of haze-related problems this year will depend on what happens in Indonesia. After the disaster of 2015, Joko Widodo, then the president, made prevention a priority. His successor, Prabowo Subianto, has kept much of that emphasis. Last year he created a new department to tackle blazes, and strengthened patrols, aerial surveillance and emergency teams. In the coming weeks, they face trial by fire. August 15TH- 21ST ｜Asia"}]},{"title":"Well Informed","titleZh":"","source":"Economist","publishedOn":"8.23","paragraphs":[{"index":1,"text":"The trillions of bugs in a human gut digest complex carbohydrates into fatty acids that provide about 10% of an individual’s calories. They synthesise vitamins, notably K (which regulates blood clotting) and various members of the B group. They help tune the immune system. They suppress the growth of pathogens. And they regulate production of signalling molecules, such as serotonin, involved in sending messages from the gut to the brain."},{"index":2,"text":"Keeping your gut microbiome in tip-top condition is thus wise. Maintaining a diverse mix of bacteria in it is widely thought a good way to do this. And, since different species have different appetites, diversity of diet makes sense."},{"index":3,"text":"In 2018 an American citizen-science project showed that people eating 30 types of plants a week had significantly more diverse microbiomes than those eating fewer than ten. And work from Stanford University, published in 2021, confirmed that fermented foods such as kimchi and sauerkraut diversify microbiomes, too. Some people, though, feel such off-the-peg advice is insufficient. They would prefer something bespoke."},{"index":4,"text":"For a suitable fistful of dollars, they can have it. So-called direct-to-consumer (D2C) firms will analyse stool samples and compile lists of the bugs therein, based on the DNA and RNA they find. Such firms may also offer tailored dietary recommendations, doses of live bacteria and special bug-friendly supplements, all intended to fill any microbial blanks that their tests have flagged up."},{"index":5,"text":"The problem with this approach is that there is no “right” microbiome to act as a reference. In fact, microbiomes can differ quite a bit from each other while still being perfectly effective at delivering a desirable outcome to their host. The biggest red flag for poor gut health is a simple lack of biodiversity—which is what a varied and partly fermented diet is good at correcting. By contrast, the idea that tinkering with the presence or absence of this or that type of bug will perceptibly improve your health has scant published scientific basis, and many D2C firms are reluctant to share the details of proprietary data on which they base their claims."},{"index":6,"text":"There are exceptions. In Britain, Tim Spector has ridden the twin horses of academic science (a post at King’s College, London) and commerce (he helped found a D2C firm called Zoe) without so far falling off. Results from Zoe’s customers are fed, with their permission, into respectable, peer-reviewed research. So far, this suggests individually tailored diets do not have huge effects, but may help at the margins."},{"index":7,"text":"However, even if a bespoke approach does have value, it must surely depend on the microbial censuses carried out by D2C firms being accurate. To test that, researchers at America’s National Institute of Standards and Technology prepared 21 sets of homogenised (and thus identical) faeces and sent three to each of seven D2C firms. When the results (which were published in February) came back there were notable differences not only between different firms’ analyses but also, in one case, between those of an individual company."},{"index":8,"text":"As Jonathan Eisen, an evolutionary microbiologist at the University of California, Davis, observes, just because microbiomes differ does not mean an era of personalised microbiome medicine is coming any time soon. In fact, he puts it more strongly than this, saying, “Most of the claims [in this area] are bogus.” Perhaps better to save your money and invest in a jar of kimchi. August 15TH- 21ST ｜Science & technology"}]}]}],"reading":[{"file":"8.17 精读.pdf","headline":{"title":"","titleZh":"","source":"","series":""},"paragraphs":[{"index":1,"en":"Torrential rain and storms in Typhoon Dolphin’s wake have inundated China’s eastern coastal region and flooded streets in Shanghai, where about 40% of flights were grounded yesterday due to the weather.","zh":"台风海豚过境后强降雨与风暴席卷我国东部沿海地区上海多处街道被淹受恶劣天气影响该市昨日约四成航班被迫停飞"},{"index":2,"en":"Dolphin packed maximum sustained winds of 94mph near its centre when it made landfall in Zhejiang, south of Shanghai, on Sunday before weakening to a tropical storm.","zh":"台风海豚于周日在上海以南的浙江登陆时中心附近最大持续风速达每小时94英里之后减弱为热带风暴"},{"index":3,"en":"More than 1.2 million people across Fujian province and the cities of Wenzhou and Shanghai were moved to safety as the typhoon approached.","zh":"台风逼近之际福建全省以及温州上海两地超120万人被转移至安全地带"},{"index":4,"en":"Many streets in Shanghai, the country’s second most populous city, were flooded, including in the main commercial","zh":"我国第二大城市上海的多条街道被洪水淹没部分主要商业中心也未能幸免"},{"index":5,"en":"The city’s two airports cancelled 943 flights as a result of the typhoon, the state broadcaster CCTV said.","zh":"据中央广播电视总台央视报道受台风影响上海两大机场共取消943架次航班"},{"index":6,"en":"A weather station in central Shanghai yesterday recorded nearly 313mm (12in) of rain in the 24 hours to 7am local time, its highest 24 hour rainfall in more than 150 years of records. Another station in the city recorded nearly 400mm.","zh":"上海市中心一处气象站监测显示截至当地时间昨日早上7点的24小时内降雨量接近313毫米12英寸创下该站点150多年有观测记录以来的24小时降雨量极值市内另一处气象站测得降雨量接近400毫米"},{"index":7,"en":"The hashtag’Shanghai turns into the sea’began trending on the Chinese social media platform Weibo as videos circulated showing flooded streets around Wukang Mansion, one of the city’s best known landmarks.","zh":"随着武康大楼周边街道被淹的视频在网上流传话题#上海变海#登上中国社交媒体微博热搜武康大楼是上海最知名的地标之一"},{"index":8,"en":"It rained almost all night last night. When I woke up this morning, I found the neighbourhood flooded, said 39 year old Hou Lina, who works in sales in Jiading in Shanghai.","zh":"昨晚几乎下了一整夜的雨今早醒来我发现小区已经被水淹了在上海嘉定从事销售工作的39岁侯丽娜说道"},{"index":9,"en":"I’ve lived in Shanghai for 10 years, and this is the first time I’ve experienced such inconvenience from a typhoon. This is the first time I’ve encountered such widespread flooding, she said.","zh":"她说我在上海生活了十年这还是头一回遭遇台风带来这么大的不便也是第一次见到范围如此大的积水内涝"},{"index":10,"en":"In Shanghai’s Jinshan, the district authority said non essential businesses and organisations could temporarily halt operations, classes, outdoor events and transit services, amid forecasts of continued strong winds and heavy rain.","zh":"上海金山区政府表示因预报显示将持续出现大风和强降雨天气非必要经营场所及机构可临时暂停营业停课停止户外活动以及公共交通运营"},{"index":11,"en":"Authorities warned that 74 rivers in the Taihu Lake basin and the coastal areas of eastern Zhejiang had exceeded warning levels, and that flood risks for small and medium sized rivers in heavy rainfall areas were high.","zh":"有关部门预警太湖流域以及浙江东部沿海共有74条河道水位已超警戒水位强降雨区域中小河流面临较高的洪水风险"},{"index":12,"en":"The strongest typhoon to hit China this year, Dolphin is forecast to move inland to the central provinces of Hubei and Henan in the coming days, while also pushing moisture north.","zh":"海豚是今年登陆我国的最强台风预报显示未来几天该台风将深入内陆抵达湖北河南中部省份同时将水汽向北输送"},{"index":13,"en":"Authorities in Beijing warned of torrential rain and said the capital was prepared to activate its flood control response this","zh":"北京相关部门发布暴雨预警表示本市已于今日上午做好启动防汛应急响应的准备"},{"index":14,"en":"Beijing was expected to experience’significant rainfall from today until Thursday, with authorities warning of flash floods in the city and landslides in surrounding mountains.","zh":"预计从今日至周四北京将迎来明显降雨有关部门警示市内可能发生短时山洪周边山区存在滑坡风险"},{"index":15,"en":"The typhoon travelled 6,000km (3,728 miles) before making landfall, giving it a life cycle three times longer than a typical typhoon, and bringing an ultra large cloud system that enveloped China’s east, CCTV said.","zh":"据央视报道台风海豚登陆前移动路径长达6000公里3728英里生命周期为普通台风的三倍并裹挟着巨型云系笼罩我国东部地区"},{"index":16,"en":"Dolphin’s impact was being compared with 2023s Typhoon Doksuri, which crossed the country after causing destruction in south eastern Fujian province, unleashing record rainfall on","zh":"海豚造成的影响被拿来与2023年台风杜苏芮作对比当年杜苏芮在福建东南部造成严重破坏后深入我国内陆给北京带来破纪录的强降雨"},{"index":17,"en":"CCTV said Beijing, Tianjin and Hebei would need to brace for heavy rain into Thursday as the storm clouds met colder air in the north.","zh":"央视表示随着风暴云团与北方冷空气相遇北京天津河北需做好应对准备强降雨将持续至周四"},{"index":18,"en":"On China’s southern coast, Hong Kong reached 36.9C on Sunday, which the Hong Kong Observatory said marked its hottest day since records began in 1884.","zh":"我国南部沿海的香港周日气温达到36.9摄氏度香港天文台称这是香港自1884年有气象记录以来的最高气温"},{"index":19,"en":"The forecaster Tropical Storm Risk said it expected the 2026 north west Pacific typhoon season to be one of the most active on record and to include 28 tropical storms, 20 typhoons and 13 intense typhoons.","zh":"气象预报机构热带风暴风险表示预计2026年西北太平洋台风季将成为有记录以来活跃度最高的台风季之一将生成28个热带风暴20个台风以及13个强台风"},{"index":20,"en":"It said the continuing strong El Niño event, high activity to date and weaker than usual trade winds across the north west Pacific basin were key reasons for the intensity of the typhoon","zh":"该机构指出持续强盛的厄尔尼诺现象迄今为止的高活跃度以及西北太平洋海域弱于常年的信风是本台风季强度偏高的主要原因"}],"vocab":[{"term":"basin","head":"n. SYN: watershed, depression Conservation projects are carried out to protect water resources within the whole river basin.","definition":"SYN: watershed, depression Conservation projects are carried out to protect water resources within the whole river basin.","gloss":"流域盆地盆状物 考研大纲词汇各类保护项目得以实施守护整个流域内的水资源","example":"","exampleZh":"","tags":[]},{"term":"torrential","head":"a. dj. SYN: heavy, violent","definition":"dj. SYN: heavy, violent","gloss":"猛烈的倾泻而下的","example":"Torrential downpours can overwhelm old drainage systems built decades ago.","exampleZh":"倾盆暴雨会让数十年前修建的老旧排水系统不堪重负","tags":[]},{"term":"inundate","head":"v. SYN: flood, submerge Low-lying residential zones became inundated after several consecutive days of persistent rain.","definition":"SYN: flood, submerge Low-lying residential zones became inundated after several consecutive days of persistent rain.","gloss":"淹没使应接不暇连续多日阴雨过后地势低洼的居民区被洪水淹没","example":"","exampleZh":"","tags":[]},{"term":"ground","head":"v. SYN: suspend Severe turbulence and low visibility grounded dozens of international flights at the coastal airport.","definition":"SYN: suspend Severe turbulence and low visibility grounded dozens of international flights at the coastal airport.","gloss":"使飞机停飞使搁浅 考研大纲词汇剧烈乱流与低能见度令这座沿海机场的数十架国际航班被迫停飞","example":"","exampleZh":"","tags":[]},{"term":"tropical","head":"a. dj. SYN: subtropical","definition":"dj. SYN: subtropical","gloss":"热带的来自热带的 考研大纲词汇","example":"Warm tropical ocean currents provide sufficient energy for the formation of violent cyclones.","exampleZh":"温暖的热带洋流为强气旋的生成提供充足能量","tags":[]},{"term":"populous","head":"a. dj. SYN: densely-populated","definition":"dj. SYN: densely-populated","gloss":"人口稠密的","example":"Some populous metropolitan regions face huge pressure in coping with extreme meteorological events.","exampleZh":"部分人口稠密的大都市区域在应对极端气象事件时面临巨大压力","tags":[]},{"term":"hashtag","head":"n. SYN: topic tag A viral social-media hashtag helps draw public attention to neglected environmental issues.","definition":"SYN: topic tag A viral social-media hashtag helps draw public attention to neglected environmental issues.","gloss":"话题标签一个爆火的社交媒体话题标签有助于将公众目光投向被忽视的环境问题","example":"","exampleZh":"","tags":[]},{"term":"circulate","head":"v. SYN: spread, distribute Unverified videos tend to circulate rapidly on short-video platforms during natural disasters.","definition":"SYN: spread, distribute Unverified videos tend to circulate rapidly on short-video platforms during natural disasters.","gloss":"传播循环流通 考研大纲词汇自然灾害期间未经核实的视频往往会在短视频平台迅速传播","example":"","exampleZh":"","tags":[]},{"term":"encounter","head":"v. SYN: experience, confront Field researchers often encounter unexpected obstacles when conducting outdoor field investigations.","definition":"SYN: experience, confront Field researchers often encounter unexpected obstacles when conducting outdoor field investigations.","gloss":"遭遇邂逅 考研大纲词汇实地调研人员开展户外考察时常常遭遇意料之外的阻碍","example":"","exampleZh":"","tags":[]},{"term":"halt","head":"v. SYN: stop, suspend Local authorities decided to halt large‑scale outdoor gatherings to avoid potential safety risks.","definition":"SYN: stop, suspend Local authorities decided to halt large‑scale outdoor gatherings to avoid potential safety risks.","gloss":"使停止中止 考研大纲词汇地方部门决定中止大型户外集会规避潜在安全隐患","example":"","exampleZh":"","tags":[]},{"term":"amid","head":"prep. SYN: among, amidst Amid growing public concern over climate risks, more cities upgrade urban drainage facilities.","definition":"SYN: among, amidst Amid growing public concern over climate risks, more cities upgrade urban drainage facilities.","gloss":"在……之中在……背景下 考研大纲词汇在公众对气候风险愈发担忧的背景下更多城市升级城市排水设施","example":"","exampleZh":"","tags":[]},{"term":"moisture","head":"n. SYN: humidity, dampness Plants in subtropical zones absorb large amounts of moisture from warm-ocean air currents.","definition":"SYN: humidity, dampness Plants in subtropical zones absorb large amounts of moisture from warm-ocean air currents.","gloss":"水汽湿气水分 考研大纲词汇亚热带植物从暖洋气流中吸收大量水汽","example":"","exampleZh":"","tags":[]},{"term":"landslide","head":"n. SYN: rockslide Continuous heavy rainfall can loosen hillside soil and trigger a destructive landslide.","definition":"SYN: rockslide Continuous heavy rainfall can loosen hillside soil and trigger a destructive landslide.","gloss":"山体滑坡一方大获全胜的选举考研大纲词汇持续暴雨会松动山坡土壤诱发破坏性山体滑坡","example":"","exampleZh":"","tags":[]},{"term":"envelope","head":"v. SYN: surround, engulf Thick fog enveloped the whole mountain range and greatly reduced visibility for drivers.","definition":"SYN: surround, engulf Thick fog enveloped the whole mountain range and greatly reduced visibility for drivers.","gloss":"笼罩包围 考研大纲词汇浓雾笼罩了整座山脉大幅降低司机的能见度","example":"","exampleZh":"","tags":[]},{"term":"unleash","head":"v. SYN: trigger, release The sudden temperature drop may unleash rounds of violent thunderstorms across the plain.","definition":"SYN: trigger, release The sudden temperature drop may unleash rounds of violent thunderstorms across the plain.","gloss":"释放引发爆发气温骤降可能会在整片平原上引发多轮猛烈雷暴","example":"","exampleZh":"","tags":[]},{"term":"brace","head":"v. SYN: prepare, fortify Communities along the river have braced for possible flood surges brought by extreme weather.","definition":"SYN: prepare, fortify Communities along the river have braced for possible flood surges brought by extreme weather.","gloss":"做好防备使抵住 考研大纲词汇沿河各社区已为极端天气可能引发的洪水激增做好防备","example":"","exampleZh":"","tags":[]}]}],"tests":[{"file":"【福利】8.17 检验题__阅读理解.docx","type":"reading","instructions":[],"passage":[],"items":[{"number":21,"stem":"According to Paragraphs 1 and 2, Typhoon Dolphin _____.","options":[{"key":"A","text":"made landfall in Zhejiang with maximum sustained winds of 94mph before weakening to a tropical storm"},{"key":"B","text":"struck Shanghai directly as a Category 5 hurricane before moving inland"},{"key":"C","text":"was downgraded to a tropical depression before reaching the Chinese coast"},{"key":"D","text":"bypassed China entirely and struck Japan's eastern coastline instead"}],"answer":"A","kicker":"[A]","analysis":["【题型】细节理解题","【难度】⭐⭐","【定位】Paragraphs 1-2","【解析】","- 原文（Para.2）：Dolphin packed maximum sustained winds of 94mph near its centre when it made landfall in Zhejiang, south of Shanghai, on Sunday before weakening to a tropical storm.","分析：","- 选项A（正确）：Para.2 明确：海豝号在浙江登陆时最大持续风速94mph，随后弱化为热带风暴。A 项精准复述。","- 选项B（错误）：使用了无中生有陷阱。原文从未说它是“五级飓风”（Category 5 hurricane），也从未说它“直接袭击上海”——它是在浙江登陆的。","- 选项C（错误）：使用了反义干扰陷阱。原文说它登陆时最大风速94mph，随后“弱化为热带风暴”（weakening to a tropical storm），而非“在到达中国海岸前就降级为热带低气压”。","- 选项D（错误）：使用了无中生有陷阱。原文明确说台风袭击了中国东部海岸，与“完全绕过中国、袭击日本”完全相反。","【命题技巧】","- 同义替换：正确选项保留了 94mph 和 Zhejiang，将 weakening to a tropical storm 完整复述。","- 无中生有：干扰项 B、D 均为纯属编造，与原文的事实描述相矛盾。"]},{"number":22,"stem":"According to Paragraph 6, the rainfall recorded at the weather station in central Shanghai was notable because _____.","options":[{"key":"A","text":"it was the highest ever recorded anywhere in China in a single day"},{"key":"B","text":"it exceeded the previous record by more than 100mm"},{"key":"C","text":"it was the first time Shanghai had recorded any rainfall during a typhoon"},{"key":"D","text":"it was the highest 24-hour rainfall recorded there in more than 150 years of records"}],"answer":"D","kicker":"[D]","analysis":["【题型】细节理解题","【难度】⭐⭐⭐","【定位】Paragraph 6","【解析】","- 原文（Para.6）：A weather station in central Shanghai yesterday recorded nearly 313mm (12in) of rain in the 24 hours to 7am local time, its highest 24-hour rainfall in more than 150 years of records.","分析：","- 选项A（错误）：使用了过度推理陷阱。原文说的是“上海超过150年的最高记录”，而非“中国有史以来单日最高”。","- 选项B（错误）：使用了无中生有陷阱。原文从未说超过前一个记录“100mm以上”，也未提及前一个记录的具体数值。","- 选项C（错误）：使用了无中生有陷阱。原文从未说“上海第一次在台风期间记录到降水”，这与常识相矛盾。","- 选项D（正确）：Para.6 明确：中心气象站记录到近313mm的降水，是“超过150年记录以来的最高单日降水量”。D 项精准复述。","【命题技巧】","- 同义替换：正确选项将 its highest 24-hour rainfall 完整保留，将 in more than 150 years of records 替换为 in more than 150 years。","- 过度推理配合：干扰项 A 将上海局部记录过度延伸为“中国全国最高”。"]},{"number":23,"stem":"It can be inferred from Paragraph 15 that Dolphin's life cycle being \"three times longer than a typical typhoon\" _____.","options":[{"key":"A","text":"means the typhoon was unusually weak and dissipated quickly after landfall"},{"key":"B","text":"contributed to its unusually large cloud system and the extensive geographic reach of its impact"},{"key":"C","text":"was caused by the storm travelling over unusually cold ocean waters"},{"key":"D","text":"had no measurable effect on the severity of flooding in eastern China"}],"answer":"B","kicker":"[B]","analysis":["【题型】推理判断题·段落推理","【难度】⭐⭐⭐⭐","【定位】Paragraph 15","【解析】","- 原文（Para.15）：The typhoon travelled 6,000km (3,728 miles) before making landfall, giving it a life cycle three times longer than a typical typhoon, and bringing an ultra-large cloud system that enveloped China’s east.","分析：","- 选项A（错误）：使用了反义干扰陷阱。原文说它带来了“超大云系统”，说明其影响范围广泛，与“异常弱、登陆后快速消散”完全相反。","- 选项B（正确）：Para.15 说台风行进了6000公里，寿命周期是典型台风的三倍，并“带来了一个超大型云系统笼罩了中国东部”。B 项将寿命周期长与其影响范围广泛逻辑拼接，属于一步推理。","- 选项C（错误）：使用了无中生有陷阱。原文从未说寿命周期长是因为“异常冷的海水”；相反，Para.20 说厄尔尼诺和弱于平常的信风是原因。","- 选项D（错误）：使用了反义干扰陷阱。原文说它带来了超大型云系统笼罩中国东部，明显加剧了洪涝严重程度，与“对洪涝严重程度无可测量的影响”相反。","【命题技巧】","- 逻辑推理：正确选项需要从“寿命周期三倍”和“超大型云系统”的并列关系中推理出因果联系。","- 反义干扰：干扰项 A、D 均与原文描述的影响相反。"]},{"number":24,"stem":"According to Paragraph 20, the Tropical Storm Risk forecaster expects the 2026 typhoon season to be exceptionally active because of _____.","options":[{"key":"A","text":"rising ocean temperatures caused entirely by natural climate cycles unrelated to human activity"},{"key":"B","text":"a sudden drop in the number of tropical storms recorded in previous years"},{"key":"C","text":"the continuing strong El Niño event, high activity to date, and weaker-than-usual trade winds"},{"key":"D","text":"a projected increase in the number of satellite monitoring systems across the Pacific"}],"answer":"C","kicker":"[C]","analysis":["【题型】细节理解题","【难度】⭐⭐⭐⭐","【定位】Paragraph 20","【解析】","- 原文（Para.20）：It said the continuing strong El Niño event, high activity to date and weaker-than-usual trade winds across the north-west Pacific basin were key reasons for the intensity of the typhoon season.","分析：","- 选项A（错误）：使用了偷换概念陷阱。原文确实提及了厄尔尼诺事件，但从未说海洋升温“完全由与人类活动无关的自然气候周期导致”。","- 选项B（错误）：使用了反义干扰陷阱。原文说的是“high activity to date”（返今为止活跃度高），与“前几年热带风暴数量骤降”相反。","- 选项C（正确）：Para.20 明确：厄尔尼诺事件持续强劲、返今活跃度高、西北太平洋信风弱于平常，是台风季强度的关键原因。C 项精准复述。","- 选项D（错误）：使用了无中生有陷阱。原文从未提及“卫星监测系统增加”与台风季强度的关系。","【命题技巧】","- 同义替换：正确选项将 continuing strong El Niño event 保留，将 weaker-than-usual trade winds 完整复述。","- 偷换概念：干扰项 A 将原文的厄尔尼诺偷换为“完全自然、与人类无关”。"]},{"number":25,"stem":"Which of the following would be the best title for the text?","options":[{"key":"A","text":"Why Beijing's Flood Control System Failed During Typhoon Dolphin"},{"key":"B","text":"'Shanghai Turns Into the Sea': Typhoon Dolphin Inundates China's East Coast"},{"key":"C","text":"The History of Typhoons in the North-West Pacific Since 1884"},{"key":"D","text":"How Climate Change Permanently Destroyed Shanghai's Infrastructure"}],"answer":"B","kicker":"[B]","analysis":["【题型】主旨大意题·标题概括","【难度】⭐⭐⭐⭐⭐","【定位】Full text","【解析】","- 原文（Para.7）：The hashtag “Shanghai turns into the sea” began trending on Weibo.","- 原文（Para.1）：Torrential rain and storms in Typhoon Dolphin’s wake have inundated China’s eastern coastal region.","分析：","- 选项A（错误）：使用了以偏概全陷阱。北京的防洪响应在 Para.13-14 被提及，但原文从未说北京防洪系统“失败”，只是说“准备启用”（prepared to activate）。","- 选项B（正确）：全文以台风海豝对中国东部海岸的洪涝影响为核心，从上海洪涝（Para.1-10）到内陆输送（Para.12）再到北京预警（Para.13-14）和季风预测（Para.19-20）。B 项引用了原文中的热词“Shanghai turns into the sea”，同时准确概括了全文核心事件。","- 选项C（错误）：使用了无中生有陷阱。原文讨论的是单一台风事件，而非“1884年以来西北太平洋台风史”。","- 选项D（错误）：使用了无中生有陷阱。原文从未说气候变化“永久毁灭了上海的基础设施”，这不是文章的论点。","【命题技巧】","- 全文脉络：正确选项需要涵盖台风对中国东部的全面影响，干扰项均以偏概全或无中生有。","- 标题特征：正确选项引用了原文中的热门词条“Shanghai turns into the sea”，既有吸引力又准确。","— — — — — — — — — —","本文档由我们自研的考研英语阅读理解大模型生成。该模型基于近10年考研英语真题进行训练。我们会根据同学们的反馈持续优化模型能力。","本文档为【福利】，不提供答疑服务，欢迎大家自行交流使用。","【两个常见问题】","随着AI技术的不断进步，通过知识投喂和持续训练，大模型已逐渐具备模仿真题命题风格的能力。这份文档正是这一尝试的成果。它仅作为福利提供给大家，起到辅助检验的作用。你可以根据自身需要选择使用，如果有所顾虑，完全可以不用。","如果对答案解析有疑惑，直接打开任何AI大模型（如Deepseek、Kimi等），上传该篇原文文档，然后复制粘贴对应的题目和选项，说清楚你的疑问，大模型会回应解释对应的问题。"]}]},{"file":"【福利】8.17检验题__完型填空.docx","type":"cloze","instructions":["Directions: Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)"],"passage":["Torrential rain and storms in Typhoon Dolphin’s wake have ____【11】____ China’s eastern coastal region and flooded streets in Shanghai, where about 40% of flights were grounded. Dolphin packed maximum sustained winds of 94mph near its centre when it ____【12】____ landfall in Zhejiang, south of Shanghai, before weakening to a tropical storm. More than 1.2 million people across Fujian province and the cities of Wenzhou and Shanghai were ____【13】____ to safety as the typhoon approached.","A weather station in central Shanghai yesterday recorded nearly 313mm of rain in 24 hours, its highest 24-hour rainfall in more than 150 years of records. The hashtag “Shanghai turns into the sea” began ____【14】____ on social media as videos circulated showing flooded streets around one of the city’s best-known landmarks.","The strongest typhoon to hit China this year, Dolphin is forecast to move ____【15】____ to the central provinces in the coming days. The typhoon travelled 6,000km before making landfall, giving it a life cycle three times longer than a ____【16】____ typhoon. Dolphin’s impact was being ____【17】____ with 2023’s Typhoon Doksuri, which crossed the country after causing destruction in Fujian province.","Authorities in Beijing warned of torrential rain and said the capital was prepared to ____【18】____ its flood control response. The forecaster said it expected the 2026 typhoon season to be one of the most ____【19】____ on record. The continuing strong El Niño event was identified as a key ____【20】____ for the intensity of the season."],"items":[{"number":11,"stem":"","options":[{"key":"A","text":"spared"},{"key":"B","text":"inundated"},{"key":"C","text":"bypassed"},{"key":"D","text":"skirted"}],"answer":"B","kicker":"B (inundated)","analysis":["【题型】动词辨析·语义场","【难度】⭐⭐","【定位】Paragraph 1, 第1句","【解析】","[A] spared（免遭）：方向相反，台风没有免遭东海岸。逻辑方向干扰。","[B] inundated（淹没、浸泡）：have inundated China’s eastern coastal region，与后文 flooded streets 一致。正确答案。","[C] bypassed（绕过）：方向相反。逻辑方向干扰。","[D] skirted（沿边缘经过）：方向相反。逻辑方向干扰。","— — — — — — — — — — —"]},{"number":12,"stem":"","options":[{"key":"A","text":"struck"},{"key":"B","text":"reached"},{"key":"C","text":"made"},{"key":"D","text":"took"}],"answer":"C","kicker":"C (made)","analysis":["【题型】动词辨析·固定搭配","【难度】⭐⭐","【定位】Paragraph 1, 第2句","【解析】","[A] struck（袭击）：struck landfall 搭配不当。搭配干扰。","[B] reached（抵达）：reached landfall 语意偏离。语义场干扰。","[C] made（发生）：made landfall（登陆）是气象学中的固定搭配。正确答案。","[D] took（采取）：took landfall 搭配不当。搭配干扰。","— — — — — — — — — — —"]},{"number":13,"stem":"","options":[{"key":"A","text":"confined"},{"key":"B","text":"returned"},{"key":"C","text":"pushed"},{"key":"D","text":"moved"}],"answer":"D","kicker":"D (moved)","analysis":["【题型】动词辨析（过去分词）·语义场","【难度】⭐⭐","【定位】Paragraph 1, 第3句","【解析】","[A] confined（限制）：语意矛盾，限制与转移到安全地带方向不符。逻辑方向干扰。","[B] returned（返回）：暗示从安全地带返回，方向相反。逻辑方向干扰。","[C] pushed（推）：语气偏强，带有强制色彩。感情色彩干扰。","[D] moved（转移）：were moved to safety（被转移到安全地带），是灾难护散中的标准表达。正确答案。","— — — — — — — — — — —"]},{"number":14,"stem":"","options":[{"key":"A","text":"trending"},{"key":"B","text":"declining"},{"key":"C","text":"disappearing"},{"key":"D","text":"fading"}],"answer":"A","kicker":"A (trending)","analysis":["【题型】动词辨析（分词）·语义场","【难度】⭐⭐","【定位】Paragraph 2, 第2句","【解析】","[A] trending（走红、热搜）：began trending on social media，trend 是社交媒体的标准用词。正确答案。","[B] declining（下降）：方向相反。逻辑方向干扰。","[C] disappearing（消失）：方向相反。逻辑方向干扰。","[D] fading（衰退）：方向相反。逻辑方向干扰。","— — — — — — — — — — —"]},{"number":15,"stem":"","options":[{"key":"A","text":"outward"},{"key":"B","text":"inland"},{"key":"C","text":"overseas"},{"key":"D","text":"abroad"}],"answer":"B","kicker":"B (inland)","analysis":["【题型】副词·方向","【难度】⭐⭐","【定位】Paragraph 3, 第1句","【解析】","[A] outward（向外、向海）：方向相反，台风向内陆移动。逻辑方向干扰。","[B] inland（向内陆）：move inland to the central provinces，与台风登陆后向内陆前进的规律一致。正确答案。","[C] overseas（向海外）：方向相反。逻辑方向干扰。","[D] abroad（向国外）：方向相反。逻辑方向干扰。","— — — — — — — — — — —"]},{"number":16,"stem":"","options":[{"key":"A","text":"typical"},{"key":"B","text":"massive"},{"key":"C","text":"historic"},{"key":"D","text":"powerful"}],"answer":"A","kicker":"A (typical)","analysis":["【题型】形容词辨析·上下文语意","【难度】⭐⭐","【定位】Paragraph 3, 第2句","【解析】","[A] typical（典型的、一般的）：three times longer than a typical typhoon，与 three times longer 的对比语境一致。正确答案。","[B] massive（庞大的）：方向不符，如果本身就庞大，对比就失去意义。语义场干扰。","[C] historic（历史性的）：语意偏离。语义场干扰。","[D] powerful（强烈的）：方向不符。语义场干扰。","— — — — — — — — — — —"]},{"number":17,"stem":"","options":[{"key":"A","text":"confused"},{"key":"B","text":"replaced"},{"key":"C","text":"compared"},{"key":"D","text":"contrasted"}],"answer":"C","kicker":"C (compared)","analysis":["【题型】动词辨析（过去分词）·固定搭配","【难度】⭐⭐","【定位】Paragraph 3, 第3句","【解析】","[A] confused（混淆）：was confused with 语意偏离，气象学家不是混淆而是对比。语义场干扰。","[B] replaced（取代）：was replaced with 语意完全不符。逻辑方向干扰。","[C] compared（对比）：was compared with 2023’s Typhoon Doksuri，compare with 是固定搭配。正确答案。","[D] contrasted（对照）：语气偏强，强调差异而非对比相似。近义干扰。","— — — — — — — — — — —"]},{"number":18,"stem":"","options":[{"key":"A","text":"cancel"},{"key":"B","text":"delay"},{"key":"C","text":"suspend"},{"key":"D","text":"activate"}],"answer":"D","kicker":"D (activate)","analysis":["【题型】动词辨析·动宾搭配","【难度】⭐⭐","【定位】Paragraph 4, 第1句","【解析】","[A] cancel（取消）：方向相反，北京不会取消防洪响应。逻辑方向干扰。","[B] delay（延迟）：方向相反。逻辑方向干扰。","[C] suspend（暂停）：方向相反。逻辑方向干扰。","[D] activate（启动、激活）：prepared to activate its flood control response，activate 是应急管理中的标准用词。正确答案。","— — — — — — — — — — —"]},{"number":19,"stem":"","options":[{"key":"A","text":"predictable"},{"key":"B","text":"active"},{"key":"C","text":"dormant"},{"key":"D","text":"stable"}],"answer":"B","kicker":"B (active)","analysis":["【题型】形容词辨析·上下文语意","【难度】⭐⭐","【定位】Paragraph 4, 第2句","【解析】","[A] predictable（可预测的）：语意偏离，文中强调的是活跃度而非可预测性。语义场干扰。","[B] active（活跃的）：one of the most active on record，与 28 tropical storms and 20 typhoons 的数据呼应。正确答案。","[C] dormant（沉睡的）：方向相反。逻辑方向干扰。","[D] stable（稳定的）：方向相反。逻辑方向干扰。","— — — — — — — — — — —"]},{"number":20,"stem":"","options":[{"key":"A","text":"reason"},{"key":"B","text":"consequence"},{"key":"C","text":"obstacle"},{"key":"D","text":"anomaly"}],"answer":"A","kicker":"A (reason)","analysis":["【题型】名词辨析·上下文语意","【难度】⭐⭐","【定位】Paragraph 4, 末句","【解析】","[A] reason（原因）：a key reason for the intensity，El Niño 是台风季强烈的原因。正确答案。","[B] consequence（后果）：方向相反，El Niño 是原因而非后果。逻辑方向干扰。","[C] obstacle（阻碍）：语意不符。语义场干扰。","[D] anomaly（异常）：语意偏离。语义场干扰。","— — — — — — — — — —","本文档由我们自研的考研英语完型填空大模型生成。该模型基于近10年考研英语真题进行训练。我们会根据同学们的反馈持续优化模型能力。","本文档为【福利】，不提供答疑服务，欢迎大家自行交流使用。","【两个常见问题】","随着AI技术的不断进步，通过知识投喂和持续训练，大模型已逐渐具备模仿真题命题风格的能力。这份文档正是这一尝试的成果。它仅作为福利提供给大家，起到辅助检验的作用。你可以根据自身需要选择使用，如果有所顾虑，完全可以不用。"]}]}],"qa":[],"originals":[{"kind":"source","label":"原文","file":"8.17—8.23 原文.docx","ext":".docx","bytes":154298,"date":"2026-08-17","range":"2026-08-17|2026-08-23","title":"","sourcePath":"D:\\外刊\\8.17—8.23 原文.docx","raw":".cache\\periodical-raw2"},{"kind":"source","label":"原文","file":"8.17—8.23 原文.pdf","ext":".pdf","bytes":382885,"date":"2026-08-17","range":"2026-08-17|2026-08-23","title":"‘Shanghai turns into the sea’ as","sourcePath":"D:\\外刊\\8.17—8.23 原文.pdf","raw":".cache\\periodical-raw2"},{"kind":"reading","label":"精读","file":"8.17 精读.pdf","ext":".pdf","bytes":1392679,"date":"2026-08-17","range":"","title":"","sourcePath":"D:\\外刊\\8.17 精读.pdf","raw":".cache\\periodical-raw2"},{"kind":"test","label":"检验题","file":"【福利】8.17 检验题__阅读理解.docx","ext":".docx","bytes":55856,"date":"2026-08-17","range":"","title":"","sourcePath":"D:\\外刊\\【福利】8.17 检验题__阅读理解.docx","raw":".cache\\periodical-raw2"},{"kind":"test","label":"检验题","file":"【福利】8.17检验题__完型填空.docx","ext":".docx","bytes":59959,"date":"2026-08-17","range":"","title":"","sourcePath":"D:\\外刊\\【福利】8.17检验题__完型填空.docx","raw":".cache\\periodical-raw2"},{"kind":"layout","label":"杂志排版","file":"8.17杂志排版.pdf","ext":".pdf","bytes":758878,"date":"2026-08-17","range":"","title":"","sourcePath":"D:\\外刊\\8.17杂志排版.pdf","raw":".cache\\periodical-raw2"}]};
